CREATE TABLE users (id uuid PRIMARY KEY, email varchar(254) UNIQUE NOT NULL, password_hash varchar(255) NOT NULL, role varchar(30) NOT NULL CHECK(role IN ('ADMIN','OPERATOR')), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_services (id varchar(50) PRIMARY KEY, name varchar(100) NOT NULL, description text NOT NULL, active boolean NOT NULL DEFAULT true);
INSERT INTO business_services(id,name,description) VALUES ('general-cargo','General Cargo Transport','Transportation of goods around Beitbridge and supported destinations.'),('removals','Removal Services','Household and office relocation requests.'),('furniture-transport','Furniture Transportation','Transportation of beds, sofas, refrigerators, tables and other furniture.'),('business-deliveries','Business Deliveries','Transportation of business stock, equipment and supplies.'),('custom-loads','Custom Loads','Goods requiring special arrangements and individual review.');
CREATE TABLE service_areas (id uuid PRIMARY KEY, name varchar(150) UNIQUE NOT NULL, verified boolean NOT NULL DEFAULT false);
INSERT INTO service_areas VALUES ('00000000-0000-0000-0000-000000000001','Beitbridge and surrounding areas',true);
CREATE TABLE vehicles (id uuid PRIMARY KEY, name varchar(100) NOT NULL, capacity_kg integer NOT NULL CHECK(capacity_kg>0), approved_photo_url text, active boolean NOT NULL DEFAULT true);
INSERT INTO vehicles(id,name,capacity_kg) VALUES ('00000000-0000-0000-0000-000000000001','3-tonne truck',3000);
CREATE TABLE customers (id uuid PRIMARY KEY, name varchar(150) NOT NULL, phone varchar(30) NOT NULL UNIQUE, email varchar(254), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotation_requests (id uuid PRIMARY KEY, reference varchar(40) UNIQUE NOT NULL, submission_key uuid UNIQUE NOT NULL, customer_id uuid NOT NULL REFERENCES customers(id), service_id varchar(50) NOT NULL REFERENCES business_services(id), pickup varchar(500) NOT NULL, destination varchar(500) NOT NULL, goods text NOT NULL, weight_kg numeric(12,2) NOT NULL CHECK(weight_kg>0), preferred_date date NOT NULL, preferred_time time NOT NULL, rate_type varchar(10) NOT NULL CHECK(rate_type IN ('DRY','WET','DISCUSS')), instructions text, review_required boolean NOT NULL, status varchar(30) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','UNDER_REVIEW','QUOTED','ACCEPTED','REJECTED','EXPIRED','CANCELLED')), price numeric(14,2) CHECK(price>0), currency varchar(3), conditions text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY, reference varchar(40) UNIQUE NOT NULL, submission_key uuid UNIQUE NOT NULL, quote_id uuid UNIQUE REFERENCES quotation_requests(id), customer_id uuid NOT NULL REFERENCES customers(id), service_id varchar(50) NOT NULL REFERENCES business_services(id), pickup varchar(500) NOT NULL, destination varchar(500) NOT NULL, goods text NOT NULL, weight_kg numeric(12,2) NOT NULL CHECK(weight_kg>0), preferred_date date NOT NULL, preferred_time time NOT NULL, rate_type varchar(10) NOT NULL CHECK(rate_type IN ('DRY','WET','DISCUSS')), instructions text, review_required boolean NOT NULL, vehicle_id uuid REFERENCES vehicles(id), driver_name varchar(150), status varchar(30) NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','PENDING_CONFIRMATION','CONFIRMED','SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leads (id uuid PRIMARY KEY, reference varchar(40) UNIQUE NOT NULL, customer_id uuid NOT NULL REFERENCES customers(id), quote_id uuid UNIQUE REFERENCES quotation_requests(id), booking_id uuid UNIQUE REFERENCES bookings(id), source varchar(30) NOT NULL, message text, status varchar(30) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','CONTACTED','QUALIFIED','QUOTATION_SENT','CONVERTED','LOST')), assigned_to uuid REFERENCES users(id), follow_up date, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_activities (id uuid PRIMARY KEY, lead_id uuid NOT NULL REFERENCES leads(id), actor varchar(254) NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor varchar(254) NOT NULL, action varchar(100) NOT NULL, resource_id varchar(100), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox (id uuid PRIMARY KEY, kind varchar(50) NOT NULL, resource_id uuid NOT NULL, recipient varchar(254), status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','FAILED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX quote_status_date ON quotation_requests(status,created_at);
CREATE INDEX booking_status_date ON bookings(status,created_at);
CREATE INDEX leads_status_date ON leads(status,created_at);
CREATE TABLE marketing_campaigns (id uuid PRIMARY KEY, name varchar(150) NOT NULL, instructions text NOT NULL, approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_accounts (id uuid PRIMARY KEY, provider varchar(30) NOT NULL CHECK(provider IN ('FACEBOOK','INSTAGRAM','LINKEDIN','TIKTOK')), display_name varchar(200) NOT NULL, external_id varchar(255) NOT NULL, token_ciphertext text NOT NULL, token_expires_at timestamptz, permissions text NOT NULL, status varchar(30) NOT NULL DEFAULT 'DISCONNECTED', UNIQUE(provider,external_id));
CREATE TABLE marketing_posts (id uuid PRIMARY KEY, campaign_id uuid REFERENCES marketing_campaigns(id), platform varchar(30) NOT NULL CHECK(platform IN ('FACEBOOK','INSTAGRAM','LINKEDIN','POSTER')), heading varchar(200) NOT NULL, caption text NOT NULL, hashtags varchar(1000) NOT NULL DEFAULT '', status varchar(30) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','APPROVED','SCHEDULED','PUBLISHED','FAILED','CANCELLED')), approved_by varchar(254), approved_at timestamptz, scheduled_at timestamptz, published_at timestamptz, platform_post_id varchar(255), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publishing_jobs (id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES marketing_posts(id), account_id uuid NOT NULL REFERENCES social_accounts(id), status varchar(30) NOT NULL CHECK(status IN ('PENDING','PROCESSING','SUCCEEDED','RETRY','FAILED','UNKNOWN','CANCELLED')), attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL, lease_until timestamptz, last_error text, UNIQUE(post_id,account_id));
CREATE INDEX jobs_due ON publishing_jobs(status,run_at);
CREATE TABLE publishing_attempts (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES publishing_jobs(id), outcome varchar(30) NOT NULL, detail text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_usage_records (id uuid PRIMARY KEY, provider varchar(30) NOT NULL, status varchar(30) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
